    (7, "函数参数做矩阵转置。", "def transpose(matrix):\n    rows = len(matrix)\n    cols = len(matrix[0])\n    result = [[matrix[j][i] for j in range(rows)] for i in range(cols)]\n    return result\n\nfor row in transpose([[1, 2], [3, 4], [5, 6]]):\n    print(row)", "填空转置参数。", "def transpose(matrix):\n    rows = len(matrix)\n    cols = len(matrix[0])\n    result = [[matrix[j][i] for j in range(rows)] for i in range(cols)]\n    return result\n\nfor row in transpose([[1, 2], [3, 4], [5, 6]]):\n    print(row)"),
    (8, "可变参数计算加权平均。", "def weighted_avg(weights, *scores):\n    total = sum(w * s for w, s in zip(weights, scores))\n    return total / sum(weights)\n\nprint(weighted_avg([1, 2], 80, 90))", "填空加权平均。", "def weighted_avg(weights, *scores):\n    total = sum(w * s for w, s in zip(weights, scores))\n    return total / sum(weights)\n\nprint(weighted_avg([1, 2], 80, 90))"),
    (9, "kwargs 实现事件分发。", "def dispatch(event, **data):\n    print(f\"Event: {event}\")\n    for k, v in data.items():\n        print(f\"  {k}: {v}\")\n\ndispatch(\"login\", user=\"alice\", ip=\"10.0.0.1\")", "填空事件分发。", "def dispatch(event, **data):\n    print(f\"Event: {event}\")\n    for k, v in data.items():\n        print(f\"  {k}: {v}\")\n\ndispatch(\"login\", user=\"alice\", ip=\"10.0.0.1\")"),
    (10, "函数参数做二分查找。", "def binary_search(nums, target, low=0, high=None):\n    if high is None:\n        high = len(nums) - 1\n    while low <= high:\n        mid = (low + high) // 2\n        if nums[mid] == target:\n            return mid\n        elif nums[mid] < target:\n            low = mid + 1\n        else:\n            high = mid - 1\n    return -1\n\nprint('Found at:', binary_search([1, 3, 5, 7, 9], 7))", "填空二分参数。", "def binary_search(nums, target, low=0, high=None):\n    if high is None:\n        high = len(nums) - 1\n    while low <= high:\n        mid = (low + high) // 2\n        if nums[mid] == target:\n            return mid\n        elif nums[mid] < target:\n            low = mid + 1\n        else:\n            high = mid - 1\n    return -1\n\nprint('Found at:', binary_search([1, 3, 5, 7, 9], 7))"),
    (11, "函数参数做快速幂。", "def fast_pow(base, exp, mod=None):\n    result = 1\n    while exp > 0:\n        if exp % 2 == 1:\n            result *= base\n            if mod:\n                result %= mod\n        base *= base\n        if mod:\n            base %= mod\n        exp //= 2\n    return result\n\nprint(fast_pow(2, 10), fast_pow(2, 10, 1000))", "填空快速幂参数。", "def fast_pow(base, exp, mod=None):\n    result = 1\n    while exp > 0:\n        if exp % 2 == 1:\n            result *= base\n            if mod:\n                result %= mod\n        base *= base\n        if mod:\n            base %= mod\n        exp //= 2\n    return result\n\nprint(fast_pow(2, 10), fast_pow(2, 10, 1000))"),
    (12, "参数传递并统计词频。", "def word_freq(*texts):\n    counts = {}\n    for t in texts:\n        for w in t.split():\n            counts[w] = counts.get(w, 0) + 1\n    return counts\n\nprint(word_freq(\"a b\", \"b c\", \"a\"))", "填空词频参数。", "def word_freq(*texts):\n    counts = {}\n    for t in texts:\n        for w in t.split():\n            counts[w] = counts.get(w, 0) + 1\n    return counts\n\nprint(word_freq(\"a b\", \"b c\", \"a\"))"),
    (13, "参数做组合数学（C(n,k)）。", "def comb(n, k):\n    if k > n:\n        return 0\n    result = 1\n    for i in range(k):\n        result = result * (n - i) // (i + 1)\n    return result\n\nprint(comb(5, 2), comb(10, 3))", "填空组合数。", "def comb(n, k):\n    if k > n:\n        return 0\n    result = 1\n    for i in range(k):\n        result = result * (n - i) // (i + 1)\n    return result\n\nprint(comb(5, 2), comb(10, 3))"),
    (14, "参数驱动多策略排序。", "def custom_sort(items, key=None, reverse=False):\n    if key:\n        items.sort(key=key, reverse=reverse)\n    else:\n        items.sort(reverse=reverse)\n    return items\n\nprint(custom_sort([\"bbb\", \"a\", \"cc\"], key=len))\nprint(custom_sort([3, 1, 2], reverse=True))", "填空排序策略。", "def custom_sort(items, key=None, reverse=False):\n    if key:\n        items.sort(key=key, reverse=reverse)\n    else:\n        items.sort(reverse=reverse)\n    return items\n\nprint(custom_sort([\"bbb\", \"a\", \"cc\"], key=len))\nprint(custom_sort([3, 1, 2], reverse=True))"),
    (15, "函数参数实现日历计算。", "def days_in_month(month, leap=False):\n    if month in (1, 3, 5, 7, 8, 10, 12):\n        return 31\n    elif month in (4, 6, 9, 11):\n        return 30\n    elif leap:\n        return 29\n    return 28\n\nprint(days_in_month(2, leap=True), days_in_month(2))", "填空日期参数。", "def days_in_month(month, leap=False):\n    if month in (1, 3, 5, 7, 8, 10, 12):\n        return 31\n    elif month in (4, 6, 9, 11):\n        return 30\n    elif leap:\n        return 29\n    return 28\n\nprint(days_in_month(2, leap=True), days_in_month(2))"),
