    (18, "参数验证并输出错误。", "def safe_int(s, default=0):\n    try:\n        return int(s)\n    except ValueError:\n        return default\n\nprint(safe_int(\"42\"), safe_int(\"abc\"))", "填空安全转换。", "def safe_int(s, default=0):\n    try:\n        return int(s)\n    except ValueError:\n        return default\n\nprint(safe_int(\"42\"), safe_int(\"abc\"))"),
    (19, "参数做矩阵乘法。", "def mat_mul(a, b):\n    result = [[0, 0], [0, 0]]\n    for i in range(2):\n        for j in range(2):\n            for k in range(2):\n                result[i][j] += a[i][k] * b[k][j]\n    return result\n\nprint(mat_mul([[1, 2], [3, 4]], [[5, 6], [7, 8]]))", "填空矩阵乘法。", "def mat_mul(a, b):\n    result = [[0, 0], [0, 0]]\n    for i in range(2):\n        for j in range(2):\n            for k in range(2):\n                result[i][j] += a[i][k] * b[k][j]\n    return result\n\nprint(mat_mul([[1, 2], [3, 4]], [[5, 6], [7, 8]]))"),
    (20, "参数实现字符串压缩。", "def compress(s, max_run=None):\n    result = \"\"\n    count = 1\n    for i in range(1, len(s)):\n        if s[i] == s[i - 1] and (max_run is None or count < max_run):\n            count += 1\n        else:\n            result += s[i - 1] + str(count)\n            count = 1\n    result += s[-1] + str(count)\n    return result\n\nprint(compress(\"aaabbb\", max_run=2))", "填空压缩参数。", "def compress(s, max_run=None):\n    result = \"\"\n    count = 1\n    for i in range(1, len(s)):\n        if s[i] == s[i - 1] and (max_run is None or count < max_run):\n            count += 1\n        else:\n            result += s[i - 1] + str(count)\n            count = 1\n    result += s[-1] + str(count)\n    return result\n\nprint(compress(\"aaabbb\", max_run=2))"),
    (21, "参数驱动筛选（多条件）。", "def filter_nums(nums, *, even=None, positive=None):\n    result = nums\n    if even is not None:\n        result = [n for n in result if (n % 2 == 0) == even]\n    if positive is not None:\n        result = [n for n in result if (n > 0) == positive]\n    return result\n\nprint(filter_nums([-2, -1, 0, 1, 2], even=True, positive=True))", "填空多条件筛选。", "def filter_nums(nums, *, even=None, positive=None):\n    result = nums\n    if even is not None:\n        result = [n for n in result if (n % 2 == 0) == even]\n    if positive is not None:\n        result = [n for n in result if (n > 0) == positive]\n    return result\n\nprint(filter_nums([-2, -1, 0, 1, 2], even=True, positive=True))"),
    (22, "参数做动态规划（简化）。", "def min_steps(n, memo=None):\n    if memo is None:\n        memo = {}\n    if n <= 1:\n        return 0\n    if n in memo:\n        return memo[n]\n    memo[n] = 1 + min_steps(n - 1, memo)\n    return memo[n]\n\nprint('Steps:', min_steps(6))", "填空 DP 参数。", "def min_steps(n, memo=None):\n    if memo is None:\n        memo = {}\n    if n <= 1:\n        return 0\n    if n in memo:\n        return memo[n]\n    memo[n] = 1 + min_steps(n - 1, memo)\n    return memo[n]\n\nprint('Steps:', min_steps(6))"),
    (23, "参数实现二分查找演示过程。", "def search_steps(nums, target):\n    low, high = 0, len(nums) - 1\n    steps = []\n    while low <= high:\n        mid = (low + high) // 2\n        steps.append(nums[mid])\n        if nums[mid] == target:\n            return steps\n        elif nums[mid] < target:\n            low = mid + 1\n        else:\n            high = mid - 1\n    return steps\n\nprint(search_steps([1, 3, 5, 7, 9, 11], 9))", "填空二分步骤。", "def search_steps(nums, target):\n    low, high = 0, len(nums) - 1\n    steps = []\n    while low <= high:\n        mid = (low + high) // 2\n        steps.append(nums[mid])\n        if nums[mid] == target:\n            return steps\n        elif nums[mid] < target:\n            low = mid + 1\n        else:\n            high = mid - 1\n    return steps\n\nprint(search_steps([1, 3, 5, 7, 9, 11], 9))"),
    (24, "参数做区间合并。", "def merge_intervals(intervals):\n    intervals.sort()\n    result = []\n    for start, end in intervals:\n        if result and start <= result[-1][1]:\n            result[-1][1] = max(result[-1][1], end)\n        else:\n            result.append([start, end])\n    return result\n\nprint(merge_intervals([[1, 3], [2, 6], [8, 10]]))", "填空区间合并。", "def merge_intervals(intervals):\n    intervals.sort()\n    result = []\n    for start, end in intervals:\n        if result and start <= result[-1][1]:\n            result[-1][1] = max(result[-1][1], end)\n        else:\n            result.append([start, end])\n    return result\n\nprint(merge_intervals([[1, 3], [2, 6], [8, 10]]))"),
